mapper.select:
select

    distinct


from (select sbd.*,sfm.field_name SECURITY_LEVEL_NAME,
             DATE_FORMAT(sbd.create_time,'%Y-%m-%d %H:%i:%m') CREATE_TIME_STR,
             DATE_FORMAT(sbd.OFFICE_TIME,'%Y-%m-%d %H:%i:%m') OFFICE_TIME_STR,
             DATE_FORMAT(sbd.UPDATE_TIME,'%Y-%m-%d %H:%i:%m') UPDATE_TIME_STR
       from safety.safety_build_device sbd
       left join safety.safety_field_manage sfm
       on sbd.SECURITY_LEVEL = sfm.field_code  and sfm.field_type = 'secretLevel_bmdj_0' and sfm.delete_falg = 0




        order by ${orderByClause}

) AS LIM


        limit ${offset}, ${limit}


        limit ${limit}

select

from (select sbd.*,sfm.field_name SECURITY_LEVEL_NAME,
DATE_FORMAT(sbd.create_time,'%Y-%m-%d %H:%i:%m') CREATE_TIME_STR,
DATE_FORMAT(sbd.OFFICE_TIME,'%Y-%m-%d %H:%i:%m') OFFICE_TIME_STR,
DATE_FORMAT(sbd.UPDATE_TIME,'%Y-%m-%d %H:%i:%m') UPDATE_TIME_STR
 from safety.safety_build_device sbd
 left join safety.safety_field_manage sfm
   on sbd.SECURITY_LEVEL = sfm.field_code  and sfm.field_type = 'secretLevel_bmdj_0' and sfm.delete_falg = 0
where sbd.DEVICE_STATUS = 1 and sbd.REMOVE_FLAG = 0


    order by ${orderByClause}

) AS LIM


        limit ${offset}, ${limit}


        limit ${limit}
